using System;using System.Drawing;using System.Windows.Forms;
internal sealed class RegionEffectsDialog:Form {
 readonly TrackBar friends=new TrackBar(),chat=new TrackBar(),input=new TrackBar(),header=new TrackBar(),navigation=new TrackBar();readonly EffectSettings original;
 readonly NumericUpDown listBlur=new NumericUpDown(),navBlur=new NumericUpDown(),inputBlur=new NumericUpDown(),saturation=new NumericUpDown(),contrast=new NumericUpDown();
 public EffectSettings Value{get{var s=original.Copy();s.Friends=friends.Value;s.Chat=chat.Value;s.Input=input.Value;s.Header=header.Value;s.Navigation=navigation.Value;s.ListBlur=(int)listBlur.Value;s.NavigationBlur=(int)navBlur.Value;s.InputBlur=(int)inputBlur.Value;s.Saturation=(int)saturation.Value;s.Contrast=(int)contrast.Value;return s;}}
 public RegionEffectsDialog(EffectSettings value){original=value.Copy();Text="背景分层与色调";Font=new Font("Microsoft YaHei UI",10);ClientSize=new Size(710,560);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;StartPosition=FormStartPosition.CenterParent;Controls.Add(new Label{Text="仅调整背景层，文字、图标和头像保持100%不透明。\n模糊以1600px窗口为参考，不是原图测量参数。",Location=new Point(20,16),Size=new Size(420,46)});Row("会话列表",friends,value.Friends,76);Row("聊天消息区域",chat,value.Chat,142);Row("输入区域",input,value.Input,208);Row("标题与搜索栏",header,value.Header,274);Row("左侧导航栏",navigation,value.Navigation,340);LayerControls(listBlur,value.ListBlur,76,0);LayerControls(inputBlur,value.InputBlur,208,2);LayerControls(navBlur,value.NavigationBlur,340,4);Number("饱和度 %",saturation,value.Saturation,0,150,406);Number("对比度 %",contrast,value.Contrast,20,150,452);var clear=new Button{Text="关闭分区蒙版",Location=new Point(20,510),Size=new Size(190,34)};Controls.Add(clear);clear.Click+=delegate{friends.Value=chat.Value=input.Value=header.Value=navigation.Value=0;listBlur.Value=navBlur.Value=inputBlur.Value=0;};var done=new Button{Text="确定",DialogResult=DialogResult.OK,Location=new Point(232,510),Size=new Size(208,34)};Controls.Add(done);AcceptButton=done;}
 void Number(string text,NumericUpDown number,int value,int min,int max,int y){Controls.Add(new Label{Text=text,Location=new Point(466,y),Size=new Size(130,24)});number.Minimum=min;number.Maximum=max;number.Value=value;number.SetBounds(602,y,88,28);Controls.Add(number);}
 void LayerControls(NumericUpDown blur,int value,int y,int region){Number("背景模糊 px",blur,value,0,30,y);var color=new Button{Text=BackgroundEffects.RegionColor(original,region),Location=new Point(466,y+30),Size=new Size(224,28)};Controls.Add(color);color.Click+=delegate{using(var picker=new StudioColorPicker{Color=ColorTranslator.FromHtml(color.Text)})if(picker.ShowDialog(this)==DialogResult.OK){color.Text=SmartPalette.Hex(picker.Color);if(region==0)original.ListColor=color.Text;else if(region==2)original.InputColor=color.Text;else original.NavigationColor=color.Text;}};} void Row(string text,TrackBar slider,int value,int y){var label=new Label{Text=text,Location=new Point(20,y),Size=new Size(280,24)};var percentage=new Label{Text=value+"%",TextAlign=ContentAlignment.TopRight,Location=new Point(350,y),Size=new Size(90,24)};Controls.Add(label);Controls.Add(percentage);slider.Minimum=0;slider.Maximum=100;slider.TickStyle=TickStyle.None;slider.Value=value;slider.SetBounds(12,y+24,436,36);Controls.Add(slider);slider.ValueChanged+=delegate{percentage.Text=slider.Value+"%";};}
}
